const original = new SyntaxError('JSON roto');
const wrapped = new Error('Configuración inválida', { cause: original });
console.log(wrapped.message);

try {
  JSON.parse('{ roto }');
} catch (error) {
  const wrapped = new Error('No se pudo leer', { cause: error });
  console.log(wrapped.cause.name);
}

function cargar(texto) {
  try { return JSON.parse(texto); }
  catch (error) { throw new Error('Configuración inválida'); }
}

function cargarConfig(texto) {
  try {
    return JSON.parse(texto);
  } catch (error) {
    return {};
  }
}
